extends Node
signal completed(resource: Resource)
signal failed(message: String)
enum State { IDLE, LOADING, READY, FAILED, CANCELLED }
var state: State = State.IDLE
var progress: float = 0.0
var path: String = ""
func begin(resource_path: String) -> Error:
    if state == State.LOADING or state == State.CANCELLED:
        return ERR_BUSY
    if resource_path.is_empty():
        return ERR_INVALID_PARAMETER
    path = resource_path
    progress = 0.0
    var err := ResourceLoader.load_threaded_request(path)
    if err != OK:
        state = State.FAILED
        failed.emit("Request failed: %s" % err)
        return err
    state = State.LOADING
    return OK
func cancel_delivery() -> void:
    if state == State.LOADING:
        state = State.CANCELLED
func _process(_delta: float) -> void:
    if state != State.LOADING and state != State.CANCELLED:
        return
    var values: Array = []
    var status := ResourceLoader.load_threaded_get_status(path, values)
    if not values.is_empty():
        progress = clampf(float(values[0]), 0.0, 1.0)
    if status == ResourceLoader.THREAD_LOAD_LOADED:
        var loaded := ResourceLoader.load_threaded_get(path)
        if state == State.CANCELLED:
            state = State.IDLE
            path = ""
            return
        if loaded == null:
            state = State.FAILED
            failed.emit("Loaded null")
            return
        state = State.READY
        progress = 1.0
        completed.emit(loaded)
    elif status == ResourceLoader.THREAD_LOAD_FAILED or status == ResourceLoader.THREAD_LOAD_INVALID_RESOURCE:
        if state == State.CANCELLED:
            state = State.IDLE
        else:
            state = State.FAILED
            failed.emit("Thread load failed or invalid")
